contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount == 10, "ticket amount must be 10 wei");
        require(address(this).balance >= amount, "insufficient balance");

        uint beforePot = c.pot();
        uint beforeBalance = address(c).balance;

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint afterPot = c.pot();
            uint afterBalance = address(c).balance;

            // The only possible balance change for a successful play with value 10 is:
            //   +10 (ticket kept, no win) or -1 (ticket kept, fee paid out)
            // The pot is reset to 0 exactly when the caller won (balance decreased by 1).
            assert(
                (afterBalance == beforeBalance + 10 && afterPot == beforePot + 10) ||
                (afterBalance == beforeBalance - 1 && afterPot == 0)
            );
        }
    }

    receive() external payable {}
}

